/* Generated by Trae Work — click-to-zoom viewer for Mermaid diagrams */
(function () {
  'use strict';

  var MIN = 0.1;
  var MAX = 8;

  var overlay = null;
  var stage = null;
  var content = null;
  var labelEl = null;

  var svg = null;
  var origin = null;
  var natW = 0;
  var natH = 0;

  var scale = 1;
  var tx = 0;
  var ty = 0;

  var drag = false;
  var startX = 0;
  var startY = 0;
  var startTx = 0;
  var startTy = 0;

  function clamp(v, lo, hi) {
    return Math.min(hi, Math.max(lo, v));
  }

  function apply() {
    content.style.transform =
      'translate(-50%, -50%) translate(' + tx + 'px, ' + ty + 'px) scale(' + scale + ')';
    if (labelEl) labelEl.textContent = Math.round(scale * 100) + '%';
  }

  function setScale(s) {
    scale = clamp(s, MIN, MAX);
    apply();
  }

  function zoomAt(factor, cx, cy) {
    var next = clamp(scale * factor, MIN, MAX);
    var ratio = next / scale;
    tx = cx - ratio * (cx - tx);
    ty = cy - ratio * (cy - ty);
    scale = next;
    apply();
  }

  function zoomBy(factor) {
    zoomAt(factor, 0, 0);
  }

  function fit() {
    var r = stage.getBoundingClientRect();
    var s = Math.min((r.width - 72) / natW, (r.height - 72) / natH);
    scale = clamp(s > 0 ? s : 0.2, 0.05, MAX);
    tx = 0;
    ty = 0;
    apply();
  }

  function open(target) {
    build();

    var vb = target.viewBox && target.viewBox.baseVal;
    natW = (vb && vb.width) ? vb.width : target.getBoundingClientRect().width;
    natH = (vb && vb.height) ? vb.height : target.getBoundingClientRect().height;
    if (!natW || !natH) return;

    svg = target;
    origin = {
      parent: svg.parentNode,
      next: svg.nextSibling,
      width: svg.getAttribute('width'),
      height: svg.getAttribute('height'),
      style: svg.getAttribute('style')
    };

    svg.setAttribute('width', natW);
    svg.setAttribute('height', natH);
    svg.style.maxWidth = 'none';

    content.innerHTML = '';
    content.appendChild(svg);

    overlay.classList.add('open');
    document.body.classList.add('zoom-lock');

    tx = 0;
    ty = 0;
    scale = 1;
    requestAnimationFrame(fit);
  }

  function close() {
    if (!overlay || !overlay.classList.contains('open')) return;
    overlay.classList.remove('open');
    document.body.classList.remove('zoom-lock');

    if (svg && origin) {
      if (origin.width === null) svg.removeAttribute('width');
      else svg.setAttribute('width', origin.width);
      if (origin.height === null) svg.removeAttribute('height');
      else svg.setAttribute('height', origin.height);
      if (origin.style === null) svg.removeAttribute('style');
      else svg.setAttribute('style', origin.style);
      if (origin.parent) origin.parent.insertBefore(svg, origin.next);
    }

    content.innerHTML = '';
    svg = null;
    origin = null;
  }

  function isOpen() {
    return !!(overlay && overlay.classList.contains('open'));
  }

  function build() {
    if (overlay) return;

    overlay = document.createElement('div');
    overlay.className = 'zoom-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-label', '图表放大查看');

    var bar = document.createElement('div');
    bar.className = 'zoom-bar';
    bar.innerHTML =
      '<button type="button" data-act="out" aria-label="缩小">-</button>' +
      '<span class="zoom-label">100%</span>' +
      '<button type="button" data-act="in" aria-label="放大">+</button>' +
      '<button type="button" data-act="fit">适应窗口</button>' +
      '<button type="button" data-act="actual">实际大小</button>' +
      '<button type="button" data-act="close">关闭</button>' +
      '<span class="zoom-tip">滚轮缩放 · 拖拽平移 · Esc 关闭</span>';

    stage = document.createElement('div');
    stage.className = 'zoom-stage';

    content = document.createElement('div');
    content.className = 'zoom-content';
    stage.appendChild(content);

    overlay.appendChild(bar);
    overlay.appendChild(stage);
    document.body.appendChild(overlay);

    labelEl = overlay.querySelector('.zoom-label');

    overlay.addEventListener('click', function (e) {
      var btn = e.target.closest ? e.target.closest('button') : null;
      if (btn) {
        var act = btn.getAttribute('data-act');
        if (act === 'in') zoomBy(1.25);
        else if (act === 'out') zoomBy(1 / 1.25);
        else if (act === 'fit') fit();
        else if (act === 'actual') setScale(1);
        else if (act === 'close') close();
        return;
      }
      if (e.target === stage) close();
    });

    overlay.addEventListener('wheel', function (e) {
      e.preventDefault();
      var r = stage.getBoundingClientRect();
      var cx = e.clientX - r.left - r.width / 2;
      var cy = e.clientY - r.top - r.height / 2;
      zoomAt(e.deltaY < 0 ? 1.12 : 1 / 1.12, cx, cy);
    }, { passive: false });

    stage.addEventListener('mousedown', function (e) {
      if (e.button !== 0) return;
      drag = true;
      startX = e.clientX;
      startY = e.clientY;
      startTx = tx;
      startTy = ty;
      stage.classList.add('dragging');
      e.preventDefault();
    });

    window.addEventListener('mousemove', function (e) {
      if (!drag) return;
      tx = startTx + (e.clientX - startX);
      ty = startTy + (e.clientY - startY);
      apply();
    });

    window.addEventListener('mouseup', function () {
      if (!drag) return;
      drag = false;
      stage.classList.remove('dragging');
    });

    document.addEventListener('keydown', function (e) {
      if (!isOpen()) return;
      if (e.key === 'Escape') {
        close();
      } else if (e.key === '+' || e.key === '=') {
        e.preventDefault();
        zoomBy(1.25);
      } else if (e.key === '-') {
        e.preventDefault();
        zoomBy(1 / 1.25);
      } else if (e.key === '0') {
        fit();
      }
    });
  }

  function addHints() {
    var figs = document.querySelectorAll('figure');
    for (var i = 0; i < figs.length; i++) {
      var fig = figs[i];
      var mermaidBlock = fig.querySelector('.mermaid');
      var title = fig.querySelector('.fig-title');
      if (!mermaidBlock || !title || title.querySelector('.zoom-hint')) continue;
      var hint = document.createElement('span');
      hint.className = 'zoom-hint';
      hint.textContent = '点击放大';
      hint.setAttribute('role', 'button');
      hint.setAttribute('tabindex', '0');
      title.appendChild(hint);
    }
  }

  document.addEventListener('click', function (e) {
    if (isOpen()) return;
    var el = e.target;
    if (!el || !el.closest) return;

    var diagram = el.closest('.mermaid svg');
    if (diagram) {
      e.preventDefault();
      open(diagram);
      return;
    }

    if (el.closest('.zoom-hint')) {
      var fig = el.closest('figure');
      var s = fig && fig.querySelector('.mermaid svg');
      if (s) {
        e.preventDefault();
        open(s);
      }
    }
  });

  document.addEventListener('keydown', function (e) {
    if (isOpen()) return;
    if (e.key !== 'Enter' && e.key !== ' ') return;
    var hint = e.target && e.target.classList && e.target.classList.contains('zoom-hint')
      ? e.target : null;
    if (!hint) return;
    e.preventDefault();
    var fig = hint.closest('figure');
    var s = fig && fig.querySelector('.mermaid svg');
    if (s) open(s);
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', addHints);
  } else {
    addHints();
  }
})();
